// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address to) public {
        vm.assume(to != address(0) && to != address(this));
        bool referenceReturnsCorrectSelector;
        try c.onERC721Received(address(0), address(0), 0, "") returns (bytes4 selector) {
            referenceReturnsCorrectSelector = (selector == bytes4(0x150b7a02));
        } catch {
            referenceReturnsCorrectSelector = false;
        }
        assertTrue(referenceReturnsCorrectSelector);
    }
}
